  def from_map(record_name, m) when is_atom(record_name) and is_map(m) do
    {:error, {:unknown_record, record_name}}
  end

  @spec encode(struct()) :: String.t()
  def encode(record) when is_struct(record) do
    JSON.encode!(to_map(record))
  end

  @spec decode(atom(), String.t()) :: {:ok, struct()} | {:error, term()}
  def decode(record_name, json) when is_atom(record_name) and is_binary(json) do
    case JSON.decode(json) do
      {:ok, m} when is_map(m) -> from_map(record_name, m)
      {:ok, other} -> {:error, {:not_a_json_object, other}}
      {:error, reason} -> {:error, reason}
    end
  end

  defp to_known_map(entries) do
    Enum.reduce(entries, %{}, fn
      {_key, nil, _kind}, acc -> acc
      {key, v, :atom}, acc -> Map.put(acc, key, Atom.to_string(v))
      {key, v, _kind}, acc -> Map.put(acc, key, v)
    end)
  end

  defp from_known_fields(m, specs, new_fun) do
    attrs =
      Enum.reduce(specs, %{}, fn {key, atom_key, kind}, acc ->
        case Map.fetch(m, key) do
          {:ok, v} -> Map.put(acc, atom_key, convert_in(kind, v))
          :error -> acc
        end
      end)

    new_fun.(attrs)
  end

  defp convert_in(:atom, v) when is_binary(v), do: String.to_atom(v)
  defp convert_in(_kind, v), do: v
end
